 // Nested dialogs (e.g. Agregar mueble) own Esc; do not close the studio.\n        if (modalOpen) return;\n        // F144: el popover de precisión se cierra antes que nada del studio.\n        if (precisionOpen) {\n          setPrecisionOpen(false);\n          return;\n        }\n        if (detailPartId || detailHardwareId) {\n          setDetailPartId(null);\n          setDetailHardwareId(null);\n          return;\n        }\n        if (selection.keys.length > 0) {\n          setSelection(EMPTY_STUDIO_SELECTION);\n          return;\n        }\n        onClose();\n        return;\n      }\n      if (modalOpen || isTyping(e.target)) return;\n      const meta = e.ctrlKey || e.metaKey;\n      const arrowsForNudge =\n        e.key === 'ArrowLeft' ||\n        e.key === 'ArrowRight' ||\n        e.key === 'ArrowUp' ||\n        e.key === 'ArrowDown';\n      if (arrowsForNudge && arrowsOwnedByWidget(e.target)) return;\n      if (meta && (e.key === 'c' || e.key === 'C')) {\n        handleCopySelection();\n        return;\n      }\n      // F144 — undo/redo por intención (§12), sin pelear con el navegador.\n      if (meta && (e.key === 'z' || e.key === 'Z')) {\n        e.preventDefault();\n        if (e.shiftKey) redoPlan();\n        else undoPlan();\n        return;\n      }\n      // F144 — Enfocar selección (acción de vista; también en modo lectura).\n      if (!meta && (e.key === 'f' || e.key === 'F')) {\n        e.preventDefault();\n        fitSelection();\n        return;\n      }\n      // F144 — nudge de teclado: la selección gana sobre la órbita (#188).\n      if (selection.keys.length > 0 && !detailMode && arrowsForNudge) {\n        const step = precision.nudgeStepFor(e.shiftKey);\n        const handled = handleNudgeSelection(\n          e.key === 'ArrowLeft' ? -step : e.key === 'ArrowRight' ? step : 0,\n          e.key === 'ArrowLeft' ? -step : e.key === 'ArrowRight' ? step : 0,\n          e.key === 'ArrowUp' ? -step : e.key === 'ArrowDown' ? step : 0,\n        );\n        if (handled) e.preventDefault();\n        return;\n      }\n      if (!canEdit) return;", "sha256": "4839c9c5ae428d2327dab71afc3f902bb4a3012b74c319877810c9d477c6a198", "kind": "SOURCE_SEMANTIC_FRAGMENT"}, {"path": "packages/ui/src/projects/components/ProjectSpatialStudio.tsx", "startLine": 1914, "endLine": 1938, "excerpt": "  const handleNudgeSelection = (\n    deltaWallMm: number,\n    deltaXMm: number,\n    deltaYMm: number,\n  ) => {\n    if (!canEdit || selection.keys.length === 0) return false;\n    const res = nudgeSelectionCommand({\n      layout,\n      footprints,\n      keys: selection.keys,\n      ...(deltaWallMm !== 0 ? { deltaWallMm } : {}),\n      ...(deltaXMm !== 0 ? { deltaXMm } : {}),\n      ...(deltaYMm !== 0 ? { deltaYMm } : {}),\n    });\n    if (!res.ok && res.reason === 'not-placed') return false;\n    runCommand(res, {\n      intent:\n        selection.keys.length === 1\n          ? 'Mover mueble'\n          : `Mover ${selection.keys.length} muebles`,\n      coalesceKey: 'nudge',\n    });\n    return res.ok;\n  };\n", "sha256": "4839c9c5ae428d2327dab71afc3f902bb4a3012b74c319877810c9d477c6a198", "kind": "SOURCE_SEMANTIC_FRAGMENT"}], "testEvidence": [], "runtimeEvidence": ["data/guest-journey.json#GUEST-J03"], "runtimeStatus": "EXISTING_GUEST_PROOF_SCOPED", "acceptance": [{"criterion": "Flechas mueven la selección completa (muro por muro; islas en plano) con paso configurable y Shift grueso; precedencia documentada input/modal > ghostDrag > nudge > órbita; nudge bloqueado enseña el motivo (aria-live) y jamás produce colisión/overflow (all-or-nothing)", "status": "NEEDS_VERIFICATION", "reason": "Fragment below does not individually certify this full criterion."}, {"criterion": "Ráfaga de nudge consecutivos = 1 entrada de undo que restaura la posición original (coalescing con ventana testeado); las entradas llevan etiqueta visible en el title de Deshacer/Rehacer", "status": "NEEDS_VERIFICATION", "reason": "Fragment below does not individually certify this full criterion."}, {"criterion": "Ajustes de precisión persistidos por dispositivo (paso nudge, snap muro on/off, umbral, gap, grilla islas) cableados a applyOffsetOnWall/placeOnWall/placeAsIsland/dragGuides; popover accesible desde el toolbar sólo con tokens", "status": "NEEDS_VERIFICATION", "reason": "Fragment below does not individually certify this full criterion."}, {"criterion": "Enfocar selección encuadra la cámara en las instancias seleccionadas (botón en barra contextual + F), sin pelear con Bounds, y funciona en modo lectura", "status": "NEEDS_VERIFICATION", "reason": "Fragment below does not individually certify this full criterion."}, {"criterion": "Drag de un módulo seleccionado traslada a sus compañeros seleccionados del mismo muro (o islas seleccionadas) conservando el arreglo; inválido bloquea con draggingInvalid sin commitear", "status": "NEEDS_VERIFICATION", "reason": "Fragment below does not individually certify this full criterion."}, {"criterion": "Dimensiones libres por ítem: inputs W/H/D validados (sólo módulos compuestos; 50–3000 mm; inválido no commitea, feedback inmediato) con chips de preset como shortcut; customDims fluye a BOM/corte/precio/3D (tests de que el precio y las partes cambian) y al fingerprint de revisión; undo restaura dims", "status": "NEEDS_VERIFICATION", "reason": "Fragment below does not individually certify this full criterion."}, {"criterion": "Inputs de offset mm commitean en blur/Enter como una intención (sin commit por tecla)", "status": "NEEDS_VERIFICATION", "reason": "Fragment below does not individually certify this full criterion."}, {"criterion": "pnpm test + pnpm typecheck verdes; smoke WebGL real: nudge ×3 → undo único restaura → a medida 800 mm → Enfocar → screenshot revisado", "status": "NEEDS_VERIFICATION", "reason": "Fragment below does not individually certify this full criterion."}]}, {"id": "F142", "name": "proyectar_materials_dock", "status": "PARTIAL", "auditDepth": "SEMANTIC_FRAG